        },
        {
          "kind": "metric",
          "sql": "SELECT 'nor' p, metric, service_name, avg(value) avg_v, max(value) max_v FROM normal_metrics WHERE service_name IN ('mysql','ts-route-service') AND metric ILIKE '%cpu%' GROUP BY 1,2,3 UNION ALL SELECT 'abn', metric, service_name, avg(value), max(value) FROM abnormal_metrics WHERE service_name IN ('mysql','ts-route-service') AND metric ILIKE '%cpu%' GROUP BY 1,2,3 ORDER BY 2,3,1",
          "claim": "CPU for route-service and mysql is lower in the abnormal period, so the slowdown is not CPU saturation."
